def solve(data):
    names = data['vary']
    rows = []
    for entry in data['entries']:
        if entry['state'] == 'live':
            route, *values = entry['key'].split('|', len(names))
            rows.append({'route': route, 'headers': dict(zip(names, values))})
    return rows

