submissions.repair-original-orphaned-bookings:
def solve(data):
    active = {}
    parents = []
    for event in sorted(data['events'], key=lambda e: (e['minute'], e['seq'])):
        name = event['id']
        if event['kind'] == 'cancel':
            del active[name]
        else:
            parents.append(active.get(event['parent']))
            active[name] = len(parents) - 1

    live_versions = set(active.values())
    supported = set()
    for version, parent in enumerate(parents):
        if version in live_versions and (parent is None or parent in supported):
            supported.add(version)
    return sorted(name for name, version in active.items() if version not in supported)

