                            break
                        i += 1
                    row.append(text[start:end].replace('""', '"'))
                else:
                    start = i
                    while i < len(text) and text[i] not in ',\r\n':
                        i += 1
                    row.append(text[start:i])
                if i == len(text) or text[i] != ',':
                    break
                i += 1
        records.append(row)
        if i < len(text):
            i += 2 if text[i] == '\r' else 1
    return records
